SourceCode.Declaration:
/// <summary>
/// The service class for sales order cancel process.
/// </summary>
class METSalesOrderService extends SysOperationServiceBase
{
    #OCCRetryCount

}

Method.Source:
    /// <summary>
    /// cancels the sales order.
    /// </summary>
    /// <param name="salesOrderRequest">
    /// The contract instance
    /// </param>
    /// <returns>
    /// The response <c>METSalesOrderCancelResponseContract</c>
    /// </returns>
    public METSalesOrderResponseContract cancelSalesOrder(METSalesOrderRequestContract salesOrderRequest)
    {
        METProcessingStatus result;
        Description255      message = "@MET:NoRecordsUpdated";

        [result, message] = this.processCancelSalesOrder(salesOrderRequest);
        
        return METSalesOrderResponseContract::newFromParameters(result, message);
    }

    /// <summary>
    /// cancels the Pick list AND sales order.
    /// </summary>
    /// <param name="pickListRequest">
    /// The contract instance
    /// </param>
    /// <returns>
    /// The response <c>METSalesOrderResponseContract</c>
    /// </returns>
    public METSalesOrderResponseContract cancelPickList(METPickListRequestContract pickListRequest)
    {
        METProcessingStatus result;
        Description255      message, pickListMessage, SalesOrderMessage;
        METSalesOrderRequestContract salesOrderRequest;
        METPickListService  pickListService;
        DataAreaId          dataAreaId;
        WMSPickingRouteID   pickingRouteId;

        WMSPickingRoute     pickingRoute;
        SalesTable          salesTable;
        Set                 salesIdList = new Set(Types::String);
        boolean             salesRecordFound;

        pickListService = METPickListService::contruct();

        [result, pickListMessage] = pickListService.processCancelPickList(pickListRequest);

        salesOrderRequest = METSalesOrderRequestContract::construct();
        
        dataAreaId = pickListRequest.parmDataAreaId();
        pickingRouteId = pickListRequest.parmPickingRouteId();
        
        salesOrderRequest.parmDataAreaId(dataAreaId);
        
        changecompany(dataAreaId)
        {
            //Pick List can have multiple Sales Orders
            //** Exists joins would not work in this scenario **
            while select  RecId, SalesId
            from    salesTable

            join    RecId 
            from    pickingRoute
            where   pickingRoute.TransType      == InventTransType::Sales
            &&      pickingRoute.transRefId     == salesTable.SalesId
            &&      pickingRoute.pickingRouteID == pickingRouteId
            {
                //process each Sales Order only once
                if(!salesIdList.in(salesTable.salesId))
                {
                    salesIdList.add(salesTable.salesId);

                    salesOrderRequest.parmSalesId(salesTable.salesId);

                    [result, SalesOrderMessage] = this.processCancelSalesOrder(salesOrderRequest);

                    salesRecordFound = true;
                }

            }

            if(!salesRecordFound)
            {
                message = "@MET:SalesOrderNotFound";
                throw error(message);
            }
            
        }
        
        message = strFmt("@MET:PlaceHolder", pickListMessage, SalesOrderMessage);

        return METSalesOrderResponseContract::newFromParameters(result, message);
    }

    /// <summary>
    /// cancels the sales order
    /// </summary>
    /// <param name="_salesOrderRequest">The contract instance</param>
    /// <returns>Container of results</returns>
    public container processCancelSalesOrder(METSalesOrderRequestContract _salesOrderRequest)
    {
        boolean             salesOrderCancelled;
        SalesUpdateRemain   salesUpdateRemain;
        METProcessingStatus result;
        Description255      message = "@MET:NoRecordsUpdated";
        SalesTable          salesTable;
        SalesId             salesId;
        DataAreaId          dataAreaId;

        salesId     = _salesOrderRequest.parmSalesId();
        dataAreaId  = _salesOrderRequest.parmDataAreaId();

        try
        {
            ttsbegin;

            changecompany(dataAreaId)
            {
                salesTable = SalesTable::find(salesId, true);
        
                if(!salesTable.RecId)
                {
                    result = METProcessingStatus::Error;
                    message = "@MET:SalesOrderNotFound";
                }
                else if(salesTable.SalesStatus != SalesStatus::Backorder)
                {
                    result = METProcessingStatus::Error;
                    message = "@MET:SalesOrderNotOpen";
                }
                else
                {
                    salesUpdateRemain = SalesUpdateRemain::construct();

                    salesOrderCancelled = salesUpdateRemain.cancelOpenOrderLinesDeliveryRemainder(salesTable);

                    if(salesOrderCancelled)
                    {
                        result = METProcessingStatus::Success;
                        message = "@MET:SalesOrderUpdateSuccessful";
                    }
                    else
                    {
                        result = METProcessingStatus::Error;
                        message =  "@MET:SalesOrderUpdateFailed";
                    }
                }

                if(result == METProcessingStatus::Error)
                {
                    throw error(message);
                }

                ttscommit;
            }
        }
        catch (Exception::Deadlock)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    error("@MET:SalesOrderUpdateFailedDatabaseDeadlock");
                    throw Exception::Deadlock;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                error("@MET:SalesOrderUpdateFailedDatabaseDeadlock");
                throw Exception::Deadlock;
            }
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    error("@MET:SalesOrderUpdateFailedDatabaseConflict");
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                error("@MET:SalesOrderUpdateFailedDatabaseConflict");
                throw Exception::UpdateConflict;
            }
        }

        return [result, message];
    }
